        "claim_boundary": "low-confidence provisional orientation seed; not an official site boundary or survey coordinate",
    }


def legacy_compatibility(c03_state: dict[str, Any], harness_metrics: dict[str, Any]) -> dict[str, Any]:
    """Reproduce the old gross-room noon proxy without contaminating v1."""
    def mass_polygon(item: dict[str, Any]):
        geometry = rect(item["x"], item["y"], item["width"], item["depth"])
        return geom_rotate(geometry, item.get("angle", 0), origin=(item["x"], item["y"]), use_radians=False) if item.get("angle") else geometry

    def legacy_shadow(item: dict[str, Any], altitude_deg: float):
        polygon = mass_polygon(item)
        distance = item["height"] / math.tan(math.radians(altitude_deg))
        moved = geom_translate(polygon, yoff=distance)
        return unary_union([polygon, moved]).convex_hull.difference(polygon)

    rooms = [item for item in c03_state["public_rooms"] if "all-weather" not in item["kind"]]
    public_union = unary_union([rect(item["x"], item["y"], item["width"], item["depth"]) for item in rooms])
    winter = unary_union(
        [unary_union([mass_polygon(item), legacy_shadow(item, 26.578)]) for item in c03_state["masses"] if not item["summer_only_shade"]]
    )
    summer = unary_union(
        [unary_union([mass_polygon(item), legacy_shadow(item, 73.458)]) for item in c03_state["masses"]]
    )
    winter_fraction = 1.0 - public_union.intersection(winter).area / public_union.area
    summer_fraction = public_union.intersection(summer).area / public_union.area
    expected = {
        "winter_public_sun_fraction": harness_metrics["winter_public_sun_fraction"],
        "summer_public_shade_fraction": harness_metrics["summer_public_shade_fraction"],
    }
    actual = {"winter_public_sun_fraction": rounded(winter_fraction), "summer_public_shade_fraction": rounded(summer_fraction)}
    return {
        "method": "isolated compatibility reproduction of the prior gross-room due-south noon proxy",
        "expected": expected,
        "actual": actual,
        "pass": actual == expected,
        "not_used_by_detailed_study": True,
    }


def input_receipt(contract: dict[str, Any]) -> dict[str, Any]:
    if not all(path.is_file() for path in (BUILDER_PATH, PACKAGE_MANIFEST, PACKAGE_COMPILER_SNAPSHOT, HARNESS_LATEST)):
        raise RuntimeError("required package/compiler/harness evidence is missing")
    compiler = json.loads(PACKAGE_COMPILER_SNAPSHOT.read_text(encoding="utf-8"))
    embedded_builder = next(item for item in compiler["source_snapshots"] if item["path"] == "tools/build_shared_floor.py")
    current_builder_sha = file_sha256(BUILDER_PATH)
    if embedded_builder["sha256"] != current_builder_sha:
        raise RuntimeError("competition package is stale relative to the prototype geometry authority")
    harness = json.loads(HARNESS_LATEST.read_text(encoding="utf-8"))
    harness_run_dir = HARNESS_LATEST.parent / harness["run_path"]
    harness_contract_path = harness_run_dir / "run_contract.json"
    harness_receipt_path = harness_run_dir / "build_receipt.json"
    c03_state_path = harness_run_dir / "candidates" / "C03-SHARED-FLOOR" / "design_state.json"
    c03_evaluation_path = harness_run_dir / "candidates" / "C03-SHARED-FLOOR" / "evaluation.json"
    if not all(path.is_file() for path in (harness_contract_path, harness_receipt_path, c03_state_path, c03_evaluation_path)):
        raise RuntimeError("latest harness run is incomplete")
    harness_contract = json.loads(harness_contract_path.read_text(encoding="utf-8"))
    harness_receipt = json.loads(harness_receipt_path.read_text(encoding="utf-8"))
    c03_state = json.loads(c03_state_path.read_text(encoding="utf-8"))
    c03_evaluation = json.loads(c03_evaluation_path.read_text(encoding="utf-8"))
    if file_sha256(harness_receipt_path) != harness["receipt_sha256"]:
        raise RuntimeError("latest harness receipt hash mismatch")
    if harness_contract.get("proposal_builder_sha256") != current_builder_sha:
        raise RuntimeError("latest harness did not evaluate the current proposal builder")
    if c03_evaluation.get("spec_hash") != value_sha256(c03_state):
        raise RuntimeError("C03 design-state hash does not match its evaluation")
    for relative, path in (
        ("candidates/C03-SHARED-FLOOR/design_state.json", c03_state_path),
        ("candidates/C03-SHARED-FLOOR/evaluation.json", c03_evaluation_path),
        ("run_contract.json", harness_contract_path),
    ):
        if harness_receipt["artifact_hashes"].get(relative) != file_sha256(path):
            raise RuntimeError(f"harness artifact receipt mismatch: {relative}")
    snapshot_compare = validate_against_harness_snapshot(c03_state)
    legacy = legacy_compatibility(c03_state, c03_evaluation["metrics"])
    if not legacy["pass"]:
        raise RuntimeError("legacy climate proxy compatibility failed")
    submitted_harness_path = PACKAGE / "visual" / "assets" / "harness-run.json"
    submitted_harness = json.loads(submitted_harness_path.read_text(encoding="utf-8"))
    if submitted_harness.get("run_id") != harness["run_id"] or submitted_harness.get("receipt_sha256") != harness["receipt_sha256"]:
        raise RuntimeError("submitted harness bundle does not point to the latest verified run")
    manifest = json.loads(PACKAGE_MANIFEST.read_text(encoding="utf-8"))
    return {
        "schema_version": "jingzhang-direct-sun-input-receipt-v1",
        "geometry_authority": "tools/build_shared_floor.py::PROTOTYPES",
        "builder_sha256": current_builder_sha,
        "prototype_payload_sha256": value_sha256(PROTOTYPES),
        "package_manifest_sha256": file_sha256(PACKAGE_MANIFEST),
        "package_state": manifest.get("package_state"),
        "embedded_builder_sha256": embedded_builder["sha256"],
        "location_seed": validate_location_seed(),
        "harness_context_only": {
            "path": HARNESS_LATEST.relative_to(WORKSPACE).as_posix(),
            "sha256": file_sha256(HARNESS_LATEST),
            "run_id": harness.get("run_id"),
            "receipt_sha256": harness["receipt_sha256"],
            "c03_design_state_sha256": file_sha256(c03_state_path),
            "c03_spec_hash": c03_evaluation["spec_hash"],
            "submitted_harness_run_sha256": file_sha256(submitted_harness_path),
            "prototype_snapshot_compare": snapshot_compare,
            "legacy_compatibility": legacy,
            "note": "The harness is context/assurance evidence, not the detailed prototype geometry authority.",
        },
        "method_source_sha256": file_sha256(Path(__file__)),
        "dependencies": dependency_versions(),
        "contract_sha256": value_sha256(contract),
    }


def convergence_checks(samples: list[dict[str, Any]], baseline_rows: dict[str, dict[str, Any]]) -> list[dict[str, Any]]:
    checks = []
    for key in PROTOTYPES:
        half = public_result(evaluate_variant(key, 0, 1, "declared", samples, 0.5))
        double = public_result(evaluate_variant(key, 0, 1, "declared", samples, 2.0))
        one = baseline_rows[key]
        comparisons = {
            "winter_mean_architecture_unshadowed_hours": max(abs(half["winter_mean_architecture_unshadowed_hours"] - one["winter_mean_architecture_unshadowed_hours"]), abs(double["winter_mean_architecture_unshadowed_hours"] - one["winter_mean_architecture_unshadowed_hours"])),
            "winter_area_fraction_architecture_unshadowed_ge_2h": max(abs(half["winter_area_fraction_architecture_unshadowed_ge_2h"] - one["winter_area_fraction_architecture_unshadowed_ge_2h"]), abs(double["winter_area_fraction_architecture_unshadowed_ge_2h"] - one["winter_area_fraction_architecture_unshadowed_ge_2h"])),
            "summer_total_mean_shadow_fraction": max(abs(half["summer_total_mean_shadow_fraction"] - one["summer_total_mean_shadow_fraction"]), abs(double["summer_total_mean_shadow_fraction"] - one["summer_total_mean_shadow_fraction"])),
        }
        passed = comparisons["winter_mean_architecture_unshadowed_hours"] <= 0.10 and comparisons["winter_area_fraction_architecture_unshadowed_ge_2h"] <= 0.02 and comparisons["summer_total_mean_shadow_fraction"] <= 0.02
        checks.append({"prototype": key, "grid_m": [0.5, 1.0, 2.0], "max_absolute_differences": {name: rounded(value) for name, value in comparisons.items()}, "pass": passed})
    return checks


